//! 🪙️ A preborn Source capsule publishes one exact bounded return-escrow snapshot.
use semio_framework_job_payload::OriginalReturnEscrowTable;
use semio_framework_value_retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedWorkOutcome,ValueError,ValueRefusalKind};
const HEADER:usize=48;const ROW:usize=136;const MAX:usize=HEADER+32*ROW;const MAX_METADATA:usize=1024;const HEADER_WORK:u64=25;
const fn metadata_bytes()->usize{std::mem::size_of::<usize>()+std::mem::size_of::<u64>()+std::mem::size_of::<Option<(u64,u64)>>() +std::mem::size_of::<Option<(u64,u32)>>() +std::mem::size_of::<Option<OriginalEscrowPublication>>()}
const fn header_metadata_bytes()->usize{2*std::mem::size_of::<usize>()+std::mem::size_of::<u64>()+3*std::mem::size_of::<u8>()+2*std::mem::size_of::<bool>()+2*std::mem::size_of::<Option<OriginalEscrowHeaderLoan>>() +std::mem::size_of::<Option<OriginalEscrowHeaderReturned>>() +3*std::mem::size_of::<Option<ValueError>>() }
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original escrow publication lost its actual Source or borrowed snapshot")}
/// 📏️ The current call reserves these currencies before its producer may run.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct OriginalEscrowPublicationDemand{pub items:usize,pub copy_bytes:usize,pub work:u64}
/// 📍️ The real preborn capsule remains borrowed while this exact extent is returned.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct OriginalEscrowPublication{pub pointer:usize,pub length:usize,pub publication:u64,pub demand:OriginalEscrowPublicationDemand}
/// 🧾️ The actual Source-owned fixed header remains loaned until its exact physical return.
pub struct OriginalEscrowHeaderLoan{owner:usize,header:usize,length:usize,capsule:usize,capsule_length:usize,publication:u64}
/// 📥️ Exact physical return is only an input to later paid Source acceptance.
pub struct OriginalEscrowHeaderReturned{owner:usize,header:usize,length:usize,capsule:usize,capsule_length:usize,publication:u64}
/// ✅️ The real Source issues this only after paid acceptance of that exact physical return.
pub struct OriginalEscrowHeaderAccepted{owner:usize,header:usize,length:usize,capsule:usize,capsule_length:usize,publication:u64}
/// ✍️ Sequential bounded writes record their own actual byte and work progress.
pub struct OriginalEscrowHeaderCursor<'a>{bytes:&'a mut[u8],written:usize,work:u64}
/// 🧾️ A header codec can target either its actual Source cursor or an ordinary bounded fixture.
pub trait OriginalEscrowHeaderWrite{fn write(&mut self,bytes:&[u8])->Result<(),ValueError>;}
impl OriginalEscrowHeaderCursor<'_>{
 pub fn write(&mut self,bytes:&[u8])->Result<(),ValueError>{if bytes.is_empty()||self.work>=HEADER_WORK{return Err(invalid())}let end=self.written.checked_add(bytes.len()).filter(|end|*end<=self.bytes.len()).ok_or_else(invalid)?;self.bytes[self.written..end].copy_from_slice(bytes);self.written=end;self.work+=1;Ok(())}
}
impl OriginalEscrowHeaderWrite for OriginalEscrowHeaderCursor<'_>{fn write(&mut self,bytes:&[u8])->Result<(),ValueError>{Self::write(self,bytes)}}
impl OriginalEscrowHeaderReturned{
 pub fn matches_acceptance(&self,accepted:&OriginalEscrowHeaderAccepted)->bool{self.owner==accepted.owner&&self.header==accepted.header&&self.length==accepted.length&&self.capsule==accepted.capsule&&self.capsule_length==accepted.capsule_length&&self.publication==accepted.publication}
}
impl OriginalEscrowHeaderLoan{
 pub fn owns_pointer(&self,pointer:usize)->bool{pointer>=self.header&&pointer.checked_sub(self.header).is_some_and(|offset|offset<self.length)}
 pub fn matches(&self,pointer:usize,length:usize)->bool{pointer==self.header&&length==self.length}
 pub fn hand_back(self,pointer:usize,length:usize)->Result<OriginalEscrowHeaderReturned,Self>{if pointer!=self.header||length!=self.length{return Err(self)}Ok(OriginalEscrowHeaderReturned{owner:self.owner,header:self.header,length:self.length,capsule:self.capsule,capsule_length:self.capsule_length,publication:self.publication})}
}
/// 📦️ This capsule is born once and remains borrowed until the Source accepts its exact handback.
pub struct OriginalEscrowPublisher{bytes:[u8;MAX],length:usize,publication:u64,acknowledged:u64,borrowed:Option<(u64,u64)>,header:[u8;184],header_length:usize,header_written:usize,header_work:u64,header_ok:bool,header_state:u8,header_codec_failure:Option<ValueError>,header_retained_failure:Option<ValueError>,header_work_failure:Option<ValueError>}
impl OriginalEscrowPublisher{
 pub const fn empty()->Self{Self{bytes:[0;MAX],length:0,publication:0,acknowledged:0,borrowed:None,header:[0;184],header_length:0,header_written:0,header_work:0,header_ok:false,header_state:0,header_codec_failure:None,header_retained_failure:None,header_work_failure:None}}
 pub fn birth_demand()->(usize,usize,u64){(std::mem::size_of::<Self>()+std::mem::size_of::<Option<Box<Self>>>(),std::mem::size_of::<Self>(),1)}
 pub fn admit(grant:RetainedCloneGrant,fuel:u64)->RetainedWorkOutcome<(Option<Box<Self>>,RetainedCloneProgress)>{let(copy,capacity,work)=Self::birth_demand();if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<copy||grant.maximum_capacity_bytes<capacity||fuel<work{return RetainedWorkOutcome{result:Ok((None,Default::default())),work:0}}let mut owner=Box::<Self>::new_uninit();unsafe{owner.as_mut_ptr().write(Self::empty());let owner=owner.assume_init();RetainedWorkOutcome{result:Ok((Some(owner),RetainedCloneProgress{copied_items:1,copied_bytes:copy,retained_capacity_bytes:capacity,..Default::default()})),work}}}
 pub fn publication_demand(rows:usize,header:usize)->Result<OriginalEscrowPublicationDemand,ValueError>{if rows>32||!matches!(header,144|152|184)||metadata_bytes()>MAX_METADATA{return Err(invalid())}Ok(OriginalEscrowPublicationDemand{items:7,copy_bytes:HEADER+ROW*rows+header+metadata_bytes(),work:109+88*rows as u64})}
 /// 🌍️ A target-independent bound counts table scans, row validation, field writes and fixed metadata; guests refuse oversized layouts before effects.
 pub fn core_wire_reserve(header:usize)->Result<OriginalEscrowPublicationDemand,ValueError>{if !matches!(header,144|152|184)||metadata_bytes()+header_metadata_bytes()>MAX_METADATA{return Err(invalid())}Ok(OriginalEscrowPublicationDemand{items:21,copy_bytes:MAX+header+MAX_METADATA,work:132+88*32})}
 pub fn core_wire_header_slot_extent()->Result<usize,ValueError>{if std::mem::size_of::<Option<OriginalEscrowHeaderLoan>>()>MAX_METADATA||std::mem::size_of::<Option<OriginalEscrowHeaderReturned>>() > MAX_METADATA{return Err(invalid())}Ok(MAX_METADATA)}
 pub fn handback_demand()->OriginalEscrowPublicationDemand{OriginalEscrowPublicationDemand{items:7,copy_bytes:std::mem::size_of::<u32>()+std::mem::size_of::<u64>()+std::mem::size_of::<Option<(u64,u32)>>() +std::mem::size_of::<Option<(u64,u64)>>() +std::mem::size_of::<usize>()+std::mem::size_of::<u8>()+std::mem::size_of::<Option<OriginalEscrowHeaderAccepted>>(),work:7}}
 pub fn header_acknowledgment_demand()->OriginalEscrowPublicationDemand{OriginalEscrowPublicationDemand{items:3,copy_bytes:std::mem::size_of::<Option<OriginalEscrowHeaderReturned>>()+std::mem::size_of::<Option<OriginalEscrowHeaderAccepted>>()+std::mem::size_of::<bool>(),work:3}}
 pub fn retirement_demand()->(usize,usize,u64){(std::mem::size_of::<Option<Box<Self>>>(),std::mem::size_of::<Self>(),1)}
 pub fn terminal_is_empty(&self)->bool{self.borrowed.is_none()&&self.header_state==0&&self.header_codec_failure.is_none()&&self.header_retained_failure.is_none()&&self.header_work_failure.is_none()}
 pub fn publication(&self)->u64{self.publication}
 pub fn borrowed(&self)->Option<&[u8]>{self.borrowed.map(|_|&self.bytes[..self.length])}
 pub fn preborn_header_address(&self)->usize{self.header.as_ptr() as usize}
 pub fn owns_header_pointer(&self,pointer:usize)->bool{pointer>=(self.header.as_ptr()as usize)&&pointer.checked_sub(self.header.as_ptr()as usize).is_some_and(|offset|offset<self.header.len())}
 pub fn header_begin_demand()->OriginalEscrowPublicationDemand{OriginalEscrowPublicationDemand{items:2,copy_bytes:std::mem::size_of::<usize>()+std::mem::size_of::<u8>(),work:2}}
 pub fn header_write_max_demand(length:usize)->Result<OriginalEscrowPublicationDemand,ValueError>{if !matches!(length,144|152|184){return Err(invalid())}Ok(OriginalEscrowPublicationDemand{items:8,copy_bytes:length+std::mem::size_of::<usize>()+std::mem::size_of::<u64>()+std::mem::size_of::<bool>()+std::mem::size_of::<u8>()+3*std::mem::size_of::<Option<ValueError>>(),work:HEADER_WORK+7})}
 pub fn header_loan_demand()->OriginalEscrowPublicationDemand{OriginalEscrowPublicationDemand{items:2,copy_bytes:std::mem::size_of::<Option<OriginalEscrowHeaderLoan>>()+std::mem::size_of::<u8>(),work:9}}
 pub fn header_return_demand()->OriginalEscrowPublicationDemand{OriginalEscrowPublicationDemand{items:2,copy_bytes:std::mem::size_of::<Option<OriginalEscrowHeaderLoan>>()+std::mem::size_of::<Option<OriginalEscrowHeaderReturned>>(),work:2}}
 pub fn header_guard_demand()->OriginalEscrowPublicationDemand{OriginalEscrowPublicationDemand{items:0,copy_bytes:0,work:2}}
 pub fn receipt_loan_ready_demand()->OriginalEscrowPublicationDemand{OriginalEscrowPublicationDemand{items:1,copy_bytes:std::mem::size_of::<bool>(),work:1}}
 pub fn begin_header(&mut self,length:usize,grant:RetainedCloneGrant,fuel:u64)->Result<bool,ValueError>{if self.borrowed.is_none()||self.header_state!=0||!matches!(length,144|152|184){return Err(invalid())}let d=Self::header_begin_demand();if grant.maximum_items<d.items||grant.maximum_depth==0||grant.maximum_copy_bytes<d.copy_bytes||fuel<d.work{return Ok(false)}self.header_length=length;self.header_state=1;Ok(true)}
 /// ✍️ The caller pays the recorded actual writes after this no-context Source borrow ends.
 pub fn with_preparing_header(&mut self,write:impl for<'loan> FnOnce(&'loan[u8],&mut OriginalEscrowHeaderCursor<'loan>)->Result<(),ValueError>)->Result<bool,ValueError>{if self.borrowed.is_none()||self.header_state!=1||self.header_codec_failure.is_some()||self.header_retained_failure.is_some()||self.header_work_failure.is_some(){return Err(invalid())}let mut cursor=OriginalEscrowHeaderCursor{bytes:&mut self.header[..self.header_length],written:0,work:0};let result=write(&self.bytes[..self.length],&mut cursor);self.header_written=cursor.written;self.header_work=cursor.work;self.header_ok=result.is_ok();if let Err(error)=result{self.header_codec_failure=Some(error)}self.header_state=2;Ok(self.header_ok)}
 pub fn header_write_demand(&self)->Result<OriginalEscrowPublicationDemand,ValueError>{if self.header_state!=2{return Err(invalid())}Ok(OriginalEscrowPublicationDemand{items:5+usize::from(self.header_codec_failure.is_some()),copy_bytes:self.header_written+std::mem::size_of::<usize>()+std::mem::size_of::<u64>()+std::mem::size_of::<bool>()+std::mem::size_of::<u8>()+if self.header_codec_failure.is_some(){std::mem::size_of::<Option<ValueError>>()}else{0},work:self.header_work+4+u64::from(self.header_codec_failure.is_some())})}
 /// 👁️ The original codec and independent posting failures remain in Source-owned cells.
 pub fn header_outcome(&self)->Result<(usize,u64,Option<&ValueError>,Option<&ValueError>,Option<&ValueError>),ValueError>{if self.header_state!=2{return Err(invalid())}Ok((self.header_written,self.header_work,self.header_codec_failure.as_ref(),self.header_retained_failure.as_ref(),self.header_work_failure.as_ref()))}
 /// 📏️ Each independent posting failure placement is a separate Source effect.
 pub fn header_post_failure_demand()->OriginalEscrowPublicationDemand{OriginalEscrowPublicationDemand{items:1,copy_bytes:std::mem::size_of::<Option<ValueError>>(),work:1}}
 /// 📥️ The caller funds each actual placement and fences a failure to post that effect.
 pub fn retain_header_post_failure(&mut self,retained:bool,error:ValueError)->Result<(),ValueError>{let slot=if retained{&mut self.header_retained_failure}else{&mut self.header_work_failure};if self.header_state!=2||slot.is_some(){return Err(error)}*slot=Some(error);Ok(())}
 /// 🧊️ The loan can originate only from this Source-owned header and capsule.
 pub fn finish_header(&mut self,destination:&mut Option<OriginalEscrowHeaderLoan>,grant:RetainedCloneGrant,fuel:u64)->Result<bool,ValueError>{if self.borrowed.is_none()||self.header_state!=2||!self.header_ok||self.header_retained_failure.is_some()||self.header_work_failure.is_some()||self.header_written!=self.header_length||destination.is_some(){return Err(invalid())}let d=Self::header_loan_demand();if grant.maximum_items<d.items||grant.maximum_depth==0||grant.maximum_copy_bytes<d.copy_bytes||fuel<d.work{return Ok(false)}let offset=if matches!(self.header_length,144|152)&&&self.header[..4]==b"SAC3"{136}else if self.header_length==184&&&self.header[..4]==b"SJH2"&&&self.header[8..12]==b"SAC3"{144}else{return Err(invalid())};let pointer=u32::from_le_bytes(self.header[offset..offset+4].try_into().unwrap());let length=u32::from_le_bytes(self.header[offset+4..offset+8].try_into().unwrap());if usize::try_from(pointer).ok()!=Some(self.bytes.as_ptr()as usize)||length as usize!=self.length{return Err(invalid())}*destination=Some(OriginalEscrowHeaderLoan{owner:self as *const Self as usize,header:self.header.as_ptr()as usize,length:self.header_length,capsule:self.bytes.as_ptr()as usize,capsule_length:self.length,publication:self.publication});self.header_state=3;Ok(true)}
 /// 👁️ The actual Source-owned bytes remain resident while the exact loan is outstanding.
 pub fn with_frozen_header<T>(&self,read:impl for<'loan> FnOnce(&'loan[u8])->T)->Result<T,ValueError>{if self.header_state!=3{return Err(invalid())}Ok(read(&self.header[..self.header_length]))}
 /// ♻️ A failed unfrozen header stays Source-owned until this paid reset.
 pub fn abort_preparing_header(&mut self,grant:RetainedCloneGrant,fuel:u64)->Result<bool,ValueError>{if !matches!(self.header_state,1|2)||self.header_codec_failure.is_some()||self.header_retained_failure.is_some()||self.header_work_failure.is_some(){return Err(invalid())}let d=Self::header_begin_demand();if grant.maximum_items<d.items||grant.maximum_depth==0||grant.maximum_copy_bytes<d.copy_bytes||fuel<d.work{return Ok(false)}self.header_state=0;self.header_length=0;Ok(true)}
 pub fn publish(&mut self,source:u64,birth:u64,recipient:u64,table:&mut OriginalReturnEscrowTable,header:usize,grant:RetainedCloneGrant,fuel:u64)->Result<Option<OriginalEscrowPublicationDemand>,ValueError>{
  if self.borrowed.is_some()||source==0||birth==0||recipient==0{return Err(invalid())}let reserve=Self::core_wire_reserve(header)?;if grant.maximum_items<reserve.items||grant.maximum_depth==0||grant.maximum_copy_bytes<reserve.copy_bytes||fuel<reserve.work{return Ok(None)}let count=table.count();let demand=Self::publication_demand(count,header)?;let next=self.publication.checked_add(1).ok_or_else(invalid)?;let revision=table.revision();let mut serial=0;for _ in 0..count{let row=table.row_after(serial).ok_or_else(invalid)?;let id=&row.identity;if id.source!=source||id.source_birth!=birth||id.recipient!=recipient||id.destination==0||id.serial<=serial||id.origin_epoch==0{return Err(invalid())}serial=id.serial;}table.borrow_snapshot(revision)?;
  let length=HEADER+count*ROW;self.bytes[..4].copy_from_slice(b"SRE1");self.bytes[4..8].copy_from_slice(&(count as u32).to_le_bytes());for(i,v)in [source,birth,recipient,next,self.acknowledged].into_iter().enumerate(){self.bytes[8+i*8..16+i*8].copy_from_slice(&v.to_le_bytes())}serial=0;for index in 0..count{let row=table.row_after(serial).expect("validated snapshot row");let id=&row.identity;let mut at=HEADER+index*ROW;macro_rules! word{($v:expr)=>{{self.bytes[at..at+8].copy_from_slice(&($v as u64).to_le_bytes());at+=8;}}}word!(id.source);word!(id.source_birth);word!(id.recipient);word!(id.destination);word!(id.extent);word!(id.serial);word!(id.origin_epoch);word!(if row.tombstone{2}else{1});word!(row.held.items);word!(row.held.copy_bytes);word!(row.held.work);word!(row.redeemed.items);word!(row.redeemed.copy_bytes);word!(row.redeemed.work);word!(row.released.items);word!(row.released.copy_bytes);word!(row.released.work);let _=at;serial=id.serial;}self.length=length;self.publication=next;self.borrowed=Some((next,revision));Ok(Some(OriginalEscrowPublicationDemand{items:demand.items-2,copy_bytes:demand.copy_bytes-header-std::mem::size_of::<Option<OriginalEscrowPublication>>(),work:demand.work-HEADER_WORK-1}))
 }
 /// 📤️ Returns only the just-published capsule's extent and paid effects from the Source lock.
 pub fn publish_extent(&mut self,source:u64,birth:u64,recipient:u64,table:&mut OriginalReturnEscrowTable,header:usize,grant:RetainedCloneGrant,fuel:u64)->Result<Option<OriginalEscrowPublication>,ValueError>{let Some(mut demand)=self.publish(source,birth,recipient,table,header,grant,fuel)? else{return Ok(None)};demand.items+=1;demand.copy_bytes+=std::mem::size_of::<Option<OriginalEscrowPublication>>();demand.work+=1;Ok(Some(OriginalEscrowPublication{pointer:self.bytes.as_ptr()as usize,length:self.length,publication:self.publication,demand}))}
 /// ✅️ The enclosing Source calls this only after accepting its exact receiving witness.
 pub fn accept_header_handback(&mut self,witness:&OriginalEscrowHeaderReturned,destination:&mut Option<OriginalEscrowHeaderAccepted>,table:&mut OriginalReturnEscrowTable,grant:RetainedCloneGrant,fuel:u64)->Result<bool,ValueError>{if destination.is_some()||self.header_state!=3||witness.owner!=self as *const Self as usize||witness.header!=self.header.as_ptr()as usize||witness.length!=self.header_length||witness.capsule!=self.bytes.as_ptr()as usize||witness.capsule_length!=self.length||witness.publication!=self.publication{return Err(invalid())}let Some((actual,revision))=self.borrowed else{return Err(invalid())};if witness.publication!=actual{return Err(invalid())}let demand=Self::handback_demand();if grant.maximum_items<demand.items||grant.maximum_depth==0||grant.maximum_copy_bytes<demand.copy_bytes||fuel<demand.work{return Ok(false)}table.hand_back_snapshot(revision)?;self.acknowledged=actual;self.borrowed=None;self.header_state=0;self.header_length=0;*destination=Some(OriginalEscrowHeaderAccepted{owner:witness.owner,header:witness.header,length:witness.length,capsule:witness.capsule,capsule_length:witness.capsule_length,publication:actual});Ok(true)}
}
